<script setup>
import {ref,computed} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {useClock} from '../../composables/useClock.js'
import {useListState} from '../../composables/useListState.js'
import {notify} from '../../composables/feedback.js'
import DataTable from '../../components/DataTable.vue'
import Pagination from '../../components/Pagination.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import MetricCard from '../../components/MetricCard.vue'
import BaseModal from '../../components/BaseModal.vue'
import {clone,columns,ordered,fmt,requestKey} from '../strategies/operationUi.js'
const r=useIrrigation(),route=useRoute(),router=useRouter(),clock=useClock(),date=d=>new Date(d.getTime()+8*3600000).toISOString().slice(0,10),state=useListState('plans',{filters:{start:clock.isReference?'2026-06-01':date(clock.now.value),end:clock.isReference?'2026-07-30':date(new Date(clock.now.value.getTime()+((r.state.entities.SystemPolicy??[])[0]?.maxScheduleDays??30)*86400000)),source:'',status:''}}),filters=ref({...state.filters}),offset=ref(-2),modal=ref(false),selected=ref(null),assessment=ref(null),busy=ref(false),failure=ref(''),reason=ref(''),key=requestKey()
const all=computed(()=>r.state.entities.Plan??[]),nodes=computed(()=>(r.state.entities.PipeNode??[]).filter(n=>n.pumpDeviceId)),steps=p=>(r.state.entities.PlanStep??[]).filter(s=>s.planId===p.planId),sourceOf=p=>{const ids=steps(p).map(s=>r.getIndex().byId.IrrigationZone.get(s.zoneId)?.sourceNodeId);return [...new Set(ids)]},rows=computed(()=>ordered(all.value.filter(p=>{const d=p.scheduledAt?.slice(0,10);return (!state.filters.start||d>=state.filters.start)&&(!state.filters.end||d<=state.filters.end)&&(!state.filters.status||p.status===state.filters.status)&&(!state.filters.source||sourceOf(p).includes(state.filters.source))}).map(p=>({...p,stepCount:steps(p).length,target:steps(p).reduce((n,s)=>n+s.targetVolumeM3,0)})),state.sort)),visible=computed(()=>rows.value.slice((state.page-1)*15,state.page*15)),days=computed(()=>Array.from({length:5},(_,i)=>{const d=new Date(clock.displayNow.value.getTime()+(offset.value+i)*86400000);return {date:date(d),label:new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',weekday:'long'}).format(d)}})),timeline=computed(()=>rows.value.filter(p=>days.value.some(d=>p.scheduledAt?.startsWith(d.date))).sort((a,b)=>({EXECUTING:0,PUBLISHED:1,DRAFT:2}[a.status]??3)-({EXECUTING:0,PUBLISHED:1,DRAFT:2}[b.status]??3)).slice(0,3)),linked=computed(()=>(r.state.entities.IrrigationRun??[]).find(x=>x.planId===selected.value?.planId))
const cols=columns([['number','#',55],['planId','计划编号',205],['name','计划名称'],['scheduledAt','计划时间',200],['stepCount','步骤',125],['target','目标m³',135],['status','状态',150]])
function edit(p){state.selectedId=p?.planId;router.push({path:p?'/plans/'+p.planId+'/edit':'/plans/new',query:{from:route.fullPath}})}
function open(p){state.selectedId=p.planId;selected.value=clone(p);assessment.value=null;failure.value='';reason.value='';modal.value=true}
async function inspect(){busy.value=true;failure.value='';try{assessment.value=await r.query('resources',{...clone(selected.value),steps:clone(steps(selected.value))})}catch(e){failure.value=e.message}finally{busy.value=false}}
async function publish(){busy.value=true;failure.value='';try{const plan=(r.state.entities.Plan??[]).find(p=>p.planId===selected.value.planId);if(!plan)throw new Error('计划不存在');if(plan.version!==selected.value.version)throw new Error('计划版本已更新，请关闭后重新打开');const checked=await r.query('resources',{...clone(plan),steps:clone(steps(plan))});assessment.value=checked;if(!checked.ok)throw new Error('当前资源检查未通过');const payload={planId:plan.planId,conflictHash:checked.conflictHash};await r.commit('PLAN_PUBLISH',payload,{expectedVersion:selected.value.version,clientRequestId:key(payload)});notify('计划已发布，运行待执行');modal.value=false}catch(e){failure.value=e.message}finally{busy.value=false}}
async function cancel(){busy.value=true;failure.value='';try{if(reason.value.trim().length<6)throw new Error('取消原因至少6字');const payload={planId:selected.value.planId,reason:reason.value};await r.commit('PLAN_CANCEL',payload,{expectedVersion:selected.value.version,clientRequestId:key(payload)});notify('待执行计划已取消');modal.value=false}catch(e){failure.value=e.message}finally{busy.value=false}}
</script>
<template><div class="page-stack plan-list"><form class="filters" @submit.prevent="state.filters={...filters};state.page=1"><label class="filter-field">开始日期<input v-model="filters.start" type="date"/></label><label class="filter-field">结束日期<input v-model="filters.end" type="date"/></label><label class="filter-field">泵站<select v-model="filters.source"><option value="">全部</option><option v-for="n in nodes" :key="n.nodeId" :value="n.nodeId">{{n.name}}</option></select></label><label class="filter-field">状态<select v-model="filters.status"><option value="">全部</option><option v-for="s in ['EXECUTING','COMPLETED','DRAFT','PUBLISHED','CANCELLED']" :key="s" :value="s">{{({EXECUTING:'执行中',COMPLETED:'已完成',DRAFT:'草稿',PUBLISHED:'已发布',CANCELLED:'已取消'})[s]}}</option></select></label><button class="btn btn-primary">查询</button><button type="button" class="btn btn-primary" :disabled="!r.can('PLAN_CREATE')" @click="edit()">新建计划</button></form><div class="stat-grid four"><MetricCard v-for="(s,i) in ['EXECUTING','COMPLETED','DRAFT','PUBLISHED']" :key="s" :label="['执行中','已完成','草稿','已发布'][i]" :value="rows.filter(p=>p.status===s).length" :icon="['run','check','plan','audit'][i]" :tone="['success','success','warning','info'][i]"/></div><section class="panel timeline-panel"><div class="timeline-heading"><h2 class="panel-title">泵站轮灌时间轴</h2><button class="btn-link" aria-label="前五天" @click="offset-=5">〈</button><span v-for="day in days" :key="day.date">{{day.label}}</span><button class="btn-link" aria-label="后五天" @click="offset+=5">〉</button></div><div v-for="p in timeline" :key="p.planId" class="timeline-row"><span>{{sourceOf(p).length>1?'全场':r.getIndex().byId.PipeNode.get(sourceOf(p)[0])?.name||p.name}}</span><div v-for="day in days" :key="day.date"><button v-if="p.scheduledAt.startsWith(day.date)" class="timeline-plan" :class="p.status.toLowerCase()" @click="open(p)"><StatusBadge :status="p.status" :text="p.status==='EXECUTING'?'运行':undefined"/></button></div></div><p v-if="!timeline.length" class="muted">这五天没有符合条件的计划</p></section><section class="panel plan-table"><DataTable :loading="!r.state.ready" compact :columns="cols" :rows="visible" row-key="planId" :selected-id="state.selectedId" :sort="state.sort" @update:sort="state.sort=$event" @row-click="edit"><template #cell-number="{index}">{{(state.page-1)*15+index+1}}</template><template #cell-planId="{row}"><button class="btn-link" @click.stop="edit(row)">{{row.planId}}</button></template><template #cell-scheduledAt="{value}">{{fmt(value,true)}}</template><template #cell-stepCount="{row}">{{steps(row).length}}</template><template #cell-target="{row}">{{steps(row).reduce((n,s)=>n+s.targetVolumeM3,0).toFixed(1)}}</template><template #cell-status="{row}"><button class="status-button" @click.stop="open(row)" aria-label="计划操作"><StatusBadge :status="row.status"/></button></template></DataTable><Pagination v-model="state.page" :total="rows.length"/></section><BaseModal v-model="modal" title="计划操作" :busy="busy" width="690px"><template v-if="selected"><p><strong>{{selected.name}}</strong> · {{selected.planId}} · V{{selected.version}}</p><p>计划时间 {{fmt(selected.scheduledAt)}} · {{steps(selected).length}} 步 · 目标 {{steps(selected).reduce((n,s)=>n+s.targetVolumeM3,0).toFixed(1)}}m³</p><p v-if="assessment">资源检查：{{assessment.ok?'通过':'未通过'}}<small v-if="assessment.ok"> · {{assessment.conflictHash}}</small></p><p v-for="(c,i) in assessment?.conflicts||[]" :key="i" class="error-text">{{c.reason||c.message||c.code}}</p><label v-if="['DRAFT','PUBLISHED'].includes(selected.status)" class="filter-field">取消待执行计划的原因<textarea v-model="reason" rows="3" placeholder="至少6字"/></label><p v-if="failure" role="alert" class="error-text">{{failure}}</p></template><template #footer><button class="btn" :disabled="busy" @click="modal=false">关闭</button><button class="btn" :disabled="busy" @click="edit(selected);modal=false">{{selected?.status==='DRAFT'?'编排':'查看编排'}}</button><button v-if="linked" class="btn" @click="router.push({path:'/runs/'+linked.runId,query:{from:route.fullPath}})">关联运行</button><button v-if="selected?.status==='DRAFT'" class="btn" :disabled="busy" @click="inspect">检查资源</button><button v-if="selected?.status==='DRAFT'" class="btn btn-primary" :disabled="busy||!r.can('PLAN_PUBLISH',selected)" @click="publish">发布</button><button v-if="['DRAFT','PUBLISHED'].includes(selected?.status)" class="btn btn-danger" :disabled="busy||!r.can('PLAN_CANCEL',selected)" @click="cancel">取消待执行计划</button></template></BaseModal></div></template>
<style scoped>.plan-list{gap:14px;margin-top:-4px}.plan-list>.filters{gap:18px;padding:0 2px}.plan-list .filter-field{flex:1}.plan-list>.filters .btn{min-width:163px}.four{grid-template-columns:repeat(4,1fr)}.four :deep(.metric-body){order:0}.four :deep(.metric-icon){order:1;margin-left:auto}.timeline-panel{height:188px;padding:16px 24px}.timeline-heading{display:grid;grid-template-columns:200px 35px repeat(5,1fr) 25px;align-items:center;margin-bottom:12px}.timeline-heading .panel-title{font-size:18px;margin:0}.timeline-heading>span{text-align:center;font-size:12px}.timeline-row{display:grid;grid-template-columns:235px repeat(5,1fr);margin-top:4px;height:33px;background:#f3f7f7;border-radius:4px;align-items:center}.timeline-row>span{padding-left:3px}.timeline-row>div{border-left:1px dashed #d1dddf;height:100%;padding:4px 12px}.timeline-plan{height:25px;width:100%;border:0;border-radius:5px;background:#e3f2e8;cursor:pointer}.timeline-plan.published{background:#e1ecfc}.timeline-plan.draft{background:#fff1d3;border:1px dashed #d8a124}.plan-table{padding:3px 3px 14px}.status-button{border:0;background:none;cursor:pointer}.plan-table :deep(.data-table.compact td){height:23px;padding-top:1px;padding-bottom:1px;line-height:20px}</style>
